import React, { useState, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Player from './components/Player';
import SearchBar from './components/SearchBar';
import TrackRow from './components/TrackRow';
import HeroBanner from './components/HeroBanner';

const DEFAULT_ARTIST = 'coldplay';
const PROXY = 'https://corsproxy.io/?';
const AUDIODB = 'https://www.theaudiodb.com/api/v1/json/123';

// ── TheAudioDB helpers ──────────────────────────────────────────────
async function adbFetch(path) {
  const url = `${AUDIODB}/${path}`;
  const res = await fetch(`${PROXY}${encodeURIComponent(url)}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}
const adbArtist  = (s) => adbFetch(`search.php?s=${encodeURIComponent(s)}`);
const adbAlbums  = (s) => adbFetch(`searchalbum.php?s=${encodeURIComponent(s)}`);
const adbTracks  = (s) => adbFetch(`searchtrack.php?s=${encodeURIComponent(s)}`);

// ── iTunes Search API – returns real 30-sec MP3 previews, no key needed ──
async function itunesSearch(artist, limit = 50) {
  const url = `https://itunes.apple.com/search?term=${encodeURIComponent(artist)}&entity=song&limit=${limit}`;
  const res = await fetch(`${PROXY}${encodeURIComponent(url)}`);
  if (!res.ok) throw new Error();
  return res.json();
}

// Build a preview map: "artist::track" → previewUrl
function buildPreviewMap(itunesResults) {
  const map = {};
  for (const r of itunesResults) {
    if (r.previewUrl) {
      const key = `${r.artistName?.toLowerCase()}::${r.trackName?.toLowerCase()}`;
      map[key] = r.previewUrl;
    }
  }
  return map;
}

function lookupPreview(map, artist, track) {
  const key = `${artist?.toLowerCase()}::${track?.toLowerCase()}`;
  return map[key] || null;
}

export default function App() {
  const [activeNav, setActiveNav]     = useState('home');
  const [tracks, setTracks]           = useState([]);
  const [albums, setAlbums]           = useState([]);
  const [artistInfo, setArtistInfo]   = useState(null);
  const [currentTrack, setCurrentTrack] = useState(null);
  const [loading, setLoading]         = useState(false);
  const [error, setError]             = useState(null);
  const [showAllTracks, setShowAllTracks] = useState(false);
  const [selectedAlbum, setSelectedAlbum] = useState(null);

  const loadArtist = useCallback(async (query) => {
    setLoading(true);
    setError(null);
    setTracks([]);
    setArtistInfo(null);
    setAlbums([]);
    setSelectedAlbum(null);
    setShowAllTracks(false);

    try {
      // Fire all 4 requests in parallel
      const [artistRes, albumsRes, tracksRes, itunesRes] = await Promise.all([
        adbArtist(query).catch(() => ({ artists: null })),
        adbAlbums(query).catch(() => ({ album: [] })),
        adbTracks(query).catch(() => ({ track: [] })),
        itunesSearch(query, 100).catch(() => ({ results: [] })),
      ]);

      const artist  = artistRes.artists?.[0]  || null;
      const adbAlbumList  = albumsRes.album   || [];
      const adbTrackList  = tracksRes.track   || [];

      if (!artist && !adbTrackList.length) {
        setError(`No results for "${query}". Try: Coldplay, Adele, Radiohead, Daft Punk.`);
        setLoading(false);
        return;
      }

      // Build iTunes preview map
      const previewMap = buildPreviewMap(itunesRes.results || []);

      // Merge TheAudioDB tracks with iTunes previews
      const merged = adbTrackList.map(t => ({
        ...t,
        preview: lookupPreview(previewMap, t.strArtist, t.strTrack),
      }));

      setArtistInfo(artist);
      setAlbums(adbAlbumList);
      setTracks(merged);
    } catch (e) {
      setError('Could not load music data. Please try again.');
    }
    setLoading(false);
  }, []);

  useEffect(() => { loadArtist(DEFAULT_ARTIST); }, [loadArtist]);

  function playTrack(track) {
    if (!track.preview) {
      // Try to load from iTunes directly as fallback
      itunesSearch(`${track.strArtist} ${track.strTrack}`, 5)
        .then(res => {
          const found = res.results?.find(r => r.previewUrl);
          if (found) {
            setCurrentTrack({
              name: track.strTrack,
              artist: track.strArtist,
              album: track.strAlbum,
              thumb: track.strTrackThumb || track.strAlbumThumb,
              preview: found.previewUrl,
            });
          } else {
            alert(`No 30-sec preview available for "${track.strTrack}"`);
          }
        })
        .catch(() => alert('Preview unavailable.'));
      return;
    }
    setCurrentTrack({
      name: track.strTrack,
      artist: track.strArtist,
      album: track.strAlbum,
      thumb: track.strTrackThumb || track.strAlbumThumb,
      preview: track.preview,
    });
  }

  const filteredTracks  = selectedAlbum
    ? tracks.filter(t => t.strAlbum === selectedAlbum)
    : tracks;
  const visibleTracks = showAllTracks ? filteredTracks : filteredTracks.slice(0, 8);

  return (
    <div style={styles.app}>
      <Sidebar active={activeNav} setActive={setActiveNav} />
      <div style={styles.main}>
        <div style={styles.content}>

          {/* Header */}
          <div style={styles.header}>
            <SearchBar onSearch={loadArtist} loading={loading} />
            <div style={styles.headerRight}>
              <button style={styles.notifBtn}>🔔</button>
            </div>
          </div>

          {error && <div style={styles.error}>{error}</div>}

          {loading && (
            <div style={styles.loadingState}>
              <div style={styles.loadingSpinner} />
              <span style={{ color: 'var(--muted)', fontSize: 14 }}>Loading music…</span>
            </div>
          )}

          {/* Artist Banner */}
          {!loading && artistInfo && (
            <div style={styles.artistBanner}>
              {artistInfo.strArtistThumb && (
                <img src={artistInfo.strArtistThumb} alt={artistInfo.strArtist} style={styles.artistThumb} />
              )}
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={styles.artistGenre}>
                  {artistInfo.strGenre || 'Music'}
                  {artistInfo.strCountry ? ` · ${artistInfo.strCountry}` : ''}
                </div>
                <div style={styles.artistName}>{artistInfo.strArtist}</div>
                <div style={styles.artistBio}>{(artistInfo.strBiographyEN || '').slice(0, 220)}…</div>
              </div>
              <div style={styles.artistStats}>
                <div style={styles.stat}>
                  <span style={styles.statNum}>{tracks.length}</span>
                  <span style={styles.statLabel}>Tracks</span>
                </div>
                <div style={styles.stat}>
                  <span style={styles.statNum}>{tracks.filter(t => t.preview).length}</span>
                  <span style={styles.statLabel}>Playable</span>
                </div>
                <div style={styles.stat}>
                  <span style={styles.statNum}>{albums.length}</span>
                  <span style={styles.statLabel}>Albums</span>
                </div>
              </div>
            </div>
          )}

          {!loading && !artistInfo && !error && <HeroBanner onPlay={() => loadArtist('coldplay')} />}

          {/* Tracks */}
          {!loading && tracks.length > 0 && (
            <div style={styles.section}>
              <div style={styles.sectionHeader}>
                <h2 style={styles.sectionTitle}>
                  {selectedAlbum ? `📀 ${selectedAlbum}` : 'Tracks'}
                </h2>
                <span style={styles.count}>{filteredTracks.length} songs</span>
                {selectedAlbum && (
                  <button style={styles.clearFilter}
                    onClick={() => { setSelectedAlbum(null); setShowAllTracks(false); }}>
                    ✕ Show all
                  </button>
                )}
              </div>
              <div style={styles.trackHeader}>
                <div style={{ width: 28 }}>#</div>
                <div style={{ width: 42 }} />
                <div style={{ flex: 1 }}>TITLE</div>
                <div style={{ width: 170 }}>ALBUM</div>
                <div style={{ width: 52, textAlign: 'right' }}>TIME</div>
                <div style={{ width: 32 }} />
              </div>
              {visibleTracks.map((t, i) => (
                <TrackRow
                  key={t.idTrack || i}
                  track={t}
                  index={i}
                  onPlay={() => playTrack(t)}
                  isPlaying={currentTrack?.name === t.strTrack && currentTrack?.artist === t.strArtist}
                  hasPreview={!!t.preview}
                />
              ))}
              {filteredTracks.length > 8 && (
                <button style={styles.seeAll} onClick={() => setShowAllTracks(s => !s)}>
                  {showAllTracks ? '▲ Show less' : `▼ Show all ${filteredTracks.length} tracks`}
                </button>
              )}
            </div>
          )}

          {/* Albums */}
          {!loading && albums.length > 0 && (
            <div style={styles.section}>
              <div style={styles.sectionHeader}>
                <h2 style={styles.sectionTitle}>Albums</h2>
                <span style={styles.count}>{albums.length} albums · click to filter tracks</span>
              </div>
              <div style={styles.albumGrid}>
                {albums.map((al, i) => {
                  const active = selectedAlbum === al.strAlbum;
                  return (
                    <div key={al.idAlbum || i}
                      style={{ ...styles.albumCard, ...(active ? styles.albumCardActive : {}) }}
                      onClick={() => { setSelectedAlbum(s => s === al.strAlbum ? null : al.strAlbum); setShowAllTracks(false); }}>
                      {al.strAlbumThumb
                        ? <img src={al.strAlbumThumb} alt={al.strAlbum} style={styles.albumThumb} />
                        : <div style={styles.albumThumbFallback}>{al.strAlbum?.[0] || '♪'}</div>}
                      <div style={styles.albumName}>{al.strAlbum}</div>
                      <div style={styles.albumYear}>{al.intYearReleased || '—'}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {!loading && !tracks.length && !error && (
            <div style={styles.emptyState}>
              <div style={styles.emptyIcon}>♪</div>
              <div style={styles.emptyText}>Search for an artist to get started</div>
              <div style={styles.suggestions}>
                {['Coldplay', 'Adele', 'Radiohead', 'Daft Punk'].map(a => (
                  <button key={a} style={styles.suggBtn} onClick={() => loadArtist(a)}>{a}</button>
                ))}
              </div>
            </div>
          )}

        </div>
        <Player track={currentTrack} />
      </div>
    </div>
  );
}

const styles = {
  app: { display: 'flex', height: '100vh', overflow: 'hidden' },
  main: { flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' },
  content: { flex: 1, overflowY: 'auto', padding: '24px 32px' },
  header: { display: 'flex', alignItems: 'center', gap: 16, marginBottom: 24 },
  headerRight: { display: 'flex', gap: 10, marginLeft: 'auto' },
  notifBtn: { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, width: 38, height: 38, cursor: 'pointer', fontSize: 16 },
  error: { background: 'rgba(247,37,133,0.1)', border: '1px solid rgba(247,37,133,0.3)', borderRadius: 10, padding: '12px 16px', color: 'var(--pink)', fontSize: 13, marginBottom: 20 },
  loadingState: { display: 'flex', alignItems: 'center', gap: 12, justifyContent: 'center', padding: 60 },
  loadingSpinner: { width: 22, height: 22, border: '2px solid var(--border)', borderTopColor: 'var(--pink)', borderRadius: '50%', animation: 'spin 0.7s linear infinite' },
  artistBanner: { display: 'flex', gap: 20, alignItems: 'center', background: 'var(--surface)', borderRadius: 16, padding: '18px 22px', marginBottom: 24, border: '1px solid var(--border)' },
  artistThumb: { width: 76, height: 76, borderRadius: 12, objectFit: 'cover', flexShrink: 0 },
  artistGenre: { fontSize: 11, fontWeight: 700, letterSpacing: 1.5, color: 'var(--pink)', textTransform: 'uppercase', marginBottom: 4 },
  artistName: { fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 22 },
  artistBio: { fontSize: 12, color: 'var(--muted)', marginTop: 6, lineHeight: 1.6 },
  artistStats: { display: 'flex', gap: 24, flexShrink: 0 },
  stat: { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 },
  statNum: { fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 20 },
  statLabel: { fontSize: 10, color: 'var(--muted)', letterSpacing: 1, textTransform: 'uppercase' },
  section: { marginBottom: 32 },
  sectionHeader: { display: 'flex', alignItems: 'center', gap: 12, marginBottom: 12 },
  sectionTitle: { fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 18 },
  count: { fontSize: 12, color: 'var(--muted)' },
  clearFilter: { marginLeft: 'auto', background: 'rgba(247,37,133,0.15)', border: '1px solid rgba(247,37,133,0.3)', borderRadius: 16, color: 'var(--pink)', fontSize: 12, padding: '4px 12px', cursor: 'pointer', fontFamily: 'var(--font-body)' },
  trackHeader: { display: 'flex', alignItems: 'center', gap: 12, padding: '0 16px 8px', borderBottom: '1px solid var(--border)', marginBottom: 4, fontSize: 11, fontWeight: 700, letterSpacing: 1, color: 'var(--muted)' },
  seeAll: { background: 'none', border: '1px solid var(--border)', borderRadius: 20, color: 'var(--muted)', fontSize: 12, padding: '8px 18px', cursor: 'pointer', marginTop: 12, fontFamily: 'var(--font-body)' },
  albumGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: 16 },
  albumCard: { cursor: 'pointer', borderRadius: 12, padding: 4, transition: 'transform .15s', border: '2px solid transparent' },
  albumCardActive: { border: '2px solid var(--pink)' },
  albumThumb: { width: '100%', aspectRatio: '1', borderRadius: 10, objectFit: 'cover', display: 'block', marginBottom: 8 },
  albumThumbFallback: { width: '100%', aspectRatio: '1', background: 'linear-gradient(135deg, var(--purple), var(--blue))', borderRadius: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 32, marginBottom: 8 },
  albumName: { fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 12, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' },
  albumYear: { fontSize: 11, color: 'var(--muted)', marginTop: 2 },
  emptyState: { display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: 60, gap: 16 },
  emptyIcon: { fontSize: 48, opacity: 0.3 },
  emptyText: { color: 'var(--muted)', fontSize: 15 },
